trial.program_source:
def transform(grid):
    h,w=len(grid),len(grid[0])
    candidates=[]
    for transpose in (False,True):
        length,depth=(h,w) if transpose else (w,h)
        for a in range(1,depth):
            for low in range(depth-a):
                for phase in range(2*a):
                    pts=[]
                    for x in range(length):
                        t=(x+phase)%(2*a)
                        y=low+min(t,2*a-t)
                        r,c=(x,y) if transpose else (y,x)
                        pts.append((r,c))
                    vals=[grid[r][c] for r,c in pts]
                    if all(vals) and len(set(vals))==1:
                        candidates.append(pts)
    out=[[0]*w for _ in range(h)]
    if candidates:
        pts=max(candidates,key=len)
        for r,c in pts: out[r][c]=grid[r][c]
    return out

